/// Asks the kernel to read the whole file into the page cache (fcntl
/// F_RDADVISE) and returns once it has. Blocks: call it off the main
/// thread. False when the file cannot be opened or the advice is refused.
@discardableResult
public static func readAhead(_ path: String) -> Bool {
    let fd = open(path, O_RDONLY)
    guard fd >= 0 else { return false }
    defer { close(fd) }
    var info = stat()
    guard fstat(fd, &info) == 0 else { return false }
    let chunk: off_t = 1 << 30 // ra_count is an Int32
    var offset: off_t = 0
    while offset < info.st_size {
        var advice = radvisory(ra_offset: offset, ra_count: Int32(min(chunk, info.st_size - offset)))
        guard fcntl(fd, F_RDADVISE, &advice) == 0 else { return false }
        offset += chunk
    }
