// ra_pread file: the app's Prewarm.readAhead in C. mincore over a read-only
// mapping, then pread every 4 MiB window that holds a missing page.
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
int main(int argc, char **argv) {
    int fd = open(argv[1], O_RDONLY); struct stat st;
    if (fd < 0 || fstat(fd, &st) != 0) { perror(argv[1]); return 1; }
    size_t size = st.st_size, page = getpagesize(), pages = (size + page - 1) / page, window = 4 << 20;
    void *map = mmap(NULL, size, PROT_READ, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) { perror("mmap"); return 1; }
    char *vec = malloc(pages);
    if (mincore(map, size, vec) != 0) { perror("mincore"); return 1; }
    char *buf = malloc(window);
    for (size_t first = 0; first < pages; ) {
        size_t last = first + window / page < pages ? first + window / page : pages;
        int missing = 0;
        for (size_t k = first; k < last; k++) if (!(vec[k] & 1)) { missing = 1; break; }
        if (missing) {
            size_t offset = first * page, length = size - offset < window ? size - offset : window, done = 0;
            while (done < length) {
                ssize_t n = pread(fd, buf, length - done, offset + done);
                if (n > 0) done += n; else if (n == 0) break; else if (errno != EINTR) { perror("pread"); return 1; }
            }
        }
        first = last;
    }
    munmap(map, size);
    return 0;
}
EOF
